#!/usr/bin/env bash

###########################################
#---------------) Colors (----------------#
###########################################

C=$(printf '\033')
RED="${C}[1;31m"
SED_RED="${C}[1;31m&${C}[0m"
GREEN="${C}[1;32m"
SED_GREEN="${C}[1;32m&${C}[0m"
YELLOW="${C}[1;33m"
SED_YELLOW="${C}[1;33m&${C}[0m"
RED_YELLOW="${C}[1;31;103m"
SED_RED_YELLOW="${C}[1;31;103m&${C}[0m"
BLUE="${C}[1;34m"
SED_BLUE="${C}[1;34m&${C}[0m"
ITALIC_BLUE="${C}[1;34m${C}[3m"
LIGHT_MAGENTA="${C}[1;95m"
SED_LIGHT_MAGENTA="${C}[1;95m&${C}[0m"
LIGHT_CYAN="${C}[1;96m"
SED_LIGHT_CYAN="${C}[1;96m&${C}[0m"
LG="${C}[1;37m" #LightGray
SED_LG="${C}[1;37m&${C}[0m"
DG="${C}[1;90m" #DarkGray
SED_DG="${C}[1;90m&${C}[0m"
NC="${C}[0m"
UNDERLINED="${C}[5m"
ITALIC="${C}[3m"


##############################################
#---------------) Packages (-----------------#
##############################################

packages=(
  curl
  wget
  git
  vim
  htop
  unzip
  build-essential
  python3
  python3-pip
  fzf
  kitty
  rofi
  texlive-lang-english
)

##############################################
#---------------) Variables (---------------#
##############################################

# tmp dir for installer
TMP_DIR=/tmp/zero-mint-installer

# Kitty config directory
KITTY_CONFIG_DIR="$HOME/.config/kitty"

# log file with timestamp
LOG_FILE="$TMP_DIR/zero-mint-install-$(date +%Y%m%d-%H%M%S).log"


##############################################
#---------------) Functions (---------------#
##############################################

# Spinner Function
spinner() {
  local pid="$1"
  local frames=( '⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏' )
  local i=0
  tput civis 2>/dev/null
  trap 'tput cnorm 2>/dev/null; echo >&2' INT TERM EXIT
  while kill -0 "$pid" 2>/dev/null; do
    printf "\r${YELLOW}[%s] Working...${RESET}" "${frames[i]}"
    i=$(( (i+1) % ${#frames[@]} ))
    sleep 0.1
  done
  printf "\r${GREEN}[✓] Done!${RESET}            \n"
  tput cnorm 2>/dev/null
  trap - INT TERM EXIT
}

# Function to create a temporary directory with error handling to log file and exit if it fails
create_tmp_dir() {
    echo -e "${GREEN} [$(date +%T)] - [*] Creating temporary directory at $TMP_DIR...${NC}"
    if ! mkdir -p "$TMP_DIR"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to create temporary directory $TMP_DIR${NC}"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Temporary directory created at $TMP_DIR${NC}"
}

# Function to create log file with error handling to log file and exit if it fails
create_log_file() {
    echo -e "${GREEN} [$(date +%T)] - [*] Creating log file at $LOG_FILE...${NC}"
    if ! touch "$LOG_FILE"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to create log file $LOG_FILE${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Log file created at $LOG_FILE${NC}" | tee -a "$LOG_FILE"
}

# function to do a basic internet connection check with error handling to log file and exit if it fails
check_internet_connection() {
    echo -e "${GREEN} [$(date +%T)] - [*] Checking internet connection...${NC}" | tee -a "$LOG_FILE"
    if ! ping -c 1 google.com &> /dev/null; then
        echo -e "${RED} [$(date +%T)] - [!] Error: No internet connection. Please check your network settings.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Internet connection is active.${NC}" | tee -a "$LOG_FILE"
}

# function to install packages with error handling to log file and exit if it fails, also tells when a package is already installed
install_packages() {
    echo -e "${GREEN} [$(date +%T)] - [*] Updating package lists...${NC}" | tee -a "$LOG_FILE"
    if ! sudo apt-get update &>> "$LOG_FILE"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to update package lists.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Package lists updated.${NC}" | tee -a "$LOG_FILE"

    for package in "${packages[@]}"; do
        echo -e "${GREEN} [$(date +%T)] - [*] Installing package: $package...${NC}" | tee -a "$LOG_FILE"
        if dpkg -s "$package" &> /dev/null; then
            echo -e "${YELLOW} [$(date +%T)] - [*] Package $package is already installed. Skipping...${NC}" | tee -a "$LOG_FILE"
            continue
        fi
        if ! sudo apt-get install -y "$package" &>> "$LOG_FILE"; then
            echo -e "${RED} [$(date +%T)] - [!] Error: Failed to install package $package.${NC}" | tee -a "$LOG_FILE"
            exit 1
        fi
        echo -e "${GREEN} [$(date +%T)] - [*] Package $package installed successfully.${NC}" | tee -a "$LOG_FILE"
    done
}

install_fonts(){
    # check if font is already installed
    if fc-list | grep -i "JetBrainsMono Nerd Font" &> /dev/null; then
        echo -e "${YELLOW} [$(date +%T)] - [*] JetBrainsMono Nerd Font is already installed. Skipping...${NC}" | tee -a "$LOG_FILE"
        return
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Downloading JetBrainsMono Nerd Font...${NC}" | tee -a "$LOG_FILE"

    if ! wget -q -O "$TMP_DIR/JetBrainsMono.zip" "https://github.com/ryanoasis/nerd-fonts/releases/download/v3.4.0/JetBrainsMono.zip"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to download JetBrainsMono Nerd Font.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Downloaded JetBrainsMono Nerd Font.${NC}" | tee -a "$LOG_FILE"
    echo -e "${GREEN} [$(date +%T)] - [*] Installing JetBrainsMono Nerd Font...${NC}" | tee -a "$LOG_FILE"
    if ! sudo unzip -o "$TMP_DIR/JetBrainsMono.zip" -d "/usr/share/fonts/truetype/" &>> "$LOG_FILE"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to unzip and install JetBrainsMono Nerd Font.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Installed JetBrainsMono Nerd Font.${NC}" | tee -a "$LOG_FILE"
    echo -e "${GREEN} [$(date +%T)] - [*] Updating font cache...${NC}" | tee -a "$LOG_FILE"
    if ! fc-cache -fv &>> "$LOG_FILE"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to update font cache.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Font cache updated.${NC}" | tee -a "$LOG_FILE"
    echo -e "${GREEN} [$(date +%T)] - [*] JetBrainsMono Nerd Font installation completed.${NC}" | tee -a "$LOG_FILE"
}

terminal_setup(){
    echo -e "${GREEN} [$(date +%T)] - [*] Setting Kitty as the default terminal emulator...${NC}" | tee -a "$LOG_FILE"
    if ! sudo update-alternatives --set x-terminal-emulator /usr/bin/kitty &>> "$LOG_FILE"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to set Kitty as the default terminal emulator.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] Kitty is now set as the default terminal emulator.${NC}" | tee -a "$LOG_FILE"

    echo -e "${GREEN} [$(date +%T)] - [*] Configuring Kitty to use JetBrainsMono Nerd Font...${NC}" | tee -a "$LOG_FILE"

    if ! mkdir -p "$KITTY_CONFIG_DIR"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to create Kitty config directory at $KITTY_CONFIG_DIR.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    # download kitty theme
    echo -e "${GREEN} [$(date +%T)] - [*] Downloading Kitty theme...${NC}" | tee -a "$LOG_FILE"
    if ! wget -q -O "$KITTY_CONFIG_DIR/snazzy.conf" "https://raw.githubusercontent.com/dexpota/kitty-themes/refs/heads/master/themes/snazzy.conf"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to download Kitty theme.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi

    # Create Kitty config file
    echo -e "${GREEN} [$(date +%T)] - [*] Creating Kitty config file at $KITTY_CONFIG_DIR/kitty.conf...${NC}" | tee -a "$LOG_FILE"
    if ! touch "$KITTY_CONFIG_DIR/kitty.conf"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to create Kitty config file at $KITTY_CONFIG_DIR/kitty.conf.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi

    # Write Kitty config
    cat <<EOL > "$KITTY_CONFIG_DIR/kitty.conf"
font_family JetBrainsMono Nerd Font
font_size 12.0
window_padding_width 10
cursor_shape beam
cursor_blink_interval 0.5
include snazzy.conf
EOL


    echo -e "${GREEN} [$(date +%T)] - [*] Kitty configuration completed. Please restart Kitty to apply the new settings.${NC}" | tee -a "$LOG_FILE"

    # check if oh-my-zsh is already installed
    if [ -d "$HOME/.oh-my-zsh" ]; then
        echo -e "${YELLOW} [$(date +%T)] - [*] oh-my-zsh is already installed. Skipping...${NC}" | tee -a "$LOG_FILE"
        return
    fi
    # Setup oh-my-zsh terminal
    echo -e "${GREEN} [$(date +%T)] - [*] Setting up oh-my-zsh terminal...${NC}" | tee -a "$LOG_FILE"
    if ! sh -c "$(curl -fsSL https://raw.githubusercontent.com/ohmyzsh/ohmyzsh/master/tools/install.sh)" "" --unattended &>> "$LOG_FILE"; then
        echo -e "${RED} [$(date +%T)] - [!] Error: Failed to install oh-my-zsh.${NC}" | tee -a "$LOG_FILE"
        exit 1
    fi
    echo -e "${GREEN} [$(date +%T)] - [*] oh-my-zsh installation completed.${NC}" | tee -a "$LOG_FILE"
}



